  staticData: { importedDocument: { html: { "className": "js-reveal", "lang": "tr" }, body: { "className": "\x6din-h-screen \x66lex \x66lex-col \x73election:\x62g-emerald-200 \x73election:\x74ext-emerald-900" } } },
  component: Index,
