function Index() {
  const [state, setState] = useState<HerbState>({ view: "map-view", region: "", province: "", plant: "mar-1", lang: "tr", query: "", photo: 0, filter: "all", copied: false });
  const update = (patch: Partial<HerbState>) => setState(previous => ({ ...previous, ...patch }));
  useEffect(() => {
    const readHash = () => { const id = new URLSearchParams(window.location.hash.slice(1)).get("plant"); if (id && plants.some(p => p.id === id)) update({ plant: id, view: "plant-page-view", photo: 0 }); };
    readHash(); window.addEventListener("hashchange", readHash); return () => window.removeEventListener("hashchange", readHash);
  }, []);
  useEffect(() => { const escape = (e: KeyboardEvent) => { if (e.key === "Escape") update({ query: "", region: "", province: "" }); }; window.addEventListener("keydown", escape); return () => window.removeEventListener("keydown", escape); }, []);
  return (
    <HerbContext value={{ state, update }}>
    <>
      <style>{capturedCSS}</style>
      <div className="fixed [left:0px] [top:0px] [width:100%] [z-index:60]" style={{ transform: "scaleX(0)" }} id="scroll-progress" aria-hidden="true" />
      <div className={"herb-bg [&]:pointer-events-none fixed [inset:0px] [overflow:hidden] [z-index:-1]"} aria-hidden="true">
        <div className={"herb-bg-img [&]:absolute will-change-transform [inset:-6%_0px]"} style={{ transform: "translate3d(0px, 0px, 0px)" }} />
        <div className={"herb-glow g1 left-[-120px] [&]:absolute top-[10%] w-[520px] [filter:blur(80px)]"} />
        <div className={"herb-glow g2 bottom-[-80px] [&]:absolute right-[-100px] w-[460px] [filter:blur(80px)]"} />
        <i className={"fa-solid fa-leaf herb-leaf l1 left-[6%] [&]:absolute top-[18%]"} />
        <i className={"fa-solid fa-seedling herb-leaf l2 left-[3%] [&]:absolute top-[62%]"} />
        <i className={"fa-solid fa-leaf herb-leaf l3 [&]:absolute right-[5%] top-[30%]"} />
        <i className={"fa-solid fa-spa herb-leaf l4 [&]:absolute right-[8%] top-[78%]"} />
        <i className={"fa-solid fa-leaf herb-leaf l5 [&]:absolute top-[48%] [left:50%]"} />
      </div>
      <ImportedHeaderETNOHERBA />
      <main className={"w-full \x6dx-auto \x70x-4 \x73m:\x70x-6 \x6cg:\x70x-8 grow [max-width:80rem] [padding-bottom:1.5rem] [padding-top:1.5rem]"}>
        <ImportedSectionTRkiyeEtnobotanikHaritas />
        <Link to="/oyun" className="game-invite"><span><b>🌿 Bilgini Test Et: Bitki Harita Oyunu</b><small>Haritadaki bitkileri rastgele soruyoruz — yetiştikleri ili bulabilir misin? 15, 30, 50 ya da tüm bitkiler.</small></span><span className="game-btn">Oyuna başla →</span></Link>
        <ImportedSectionKazdaGKnar />
        <ImportedSectionQRKodYazdRma />
      </main>
      <ImportedFooter />
    </>
    </HerbContext>
  );
}

